"""Collect bundled native-parser notices from the downloaded Go modules."""

import json
from pathlib import Path
import subprocess


used_modules = set(subprocess.check_output(
    ["go", "list", "-deps", "-f", "{{with .Module}}{{.Path}}{{end}}", "./cmd/norm"],
    text=True,
).splitlines())
output = subprocess.check_output(["go", "list", "-m", "-json", "all"], text=True)
decoder = json.JSONDecoder()
destination = Path("bin/release-licenses")
destination.mkdir(parents=True, exist_ok=True)
# Remove only notices generated by this script on a previous local build.
for previous in destination.glob("github.com__*"):
    previous.unlink()
count = 0
while output.strip():
    module, end = decoder.raw_decode(output.lstrip())
    output = output.lstrip()[end:]
    name = module["Path"]
    if not name.startswith("github.com/tree-sitter/") and name != "github.com/mattn/go-pointer":
        continue
    # Exclude grammars used only by upstream tests, not our executable.
    if name not in used_modules:
        continue
    root = Path(module["Dir"])
    notices = sorted(
        path for path in root.rglob("*")
        if path.is_file() and path.name.upper().startswith(("LICENSE", "COPYING", "NOTICE"))
    )
    if not notices:
        raise SystemExit(f"No license found for {name}; refusing to package")
    # Flatten relative paths, retaining module and path identity. This also
    # includes the Unicode notice embedded in the Tree-sitter runtime sources.
    for path in notices:
        filename = name.replace("/", "__") + "__" + "__".join(path.relative_to(root).parts)
        (destination / filename).write_bytes(path.read_bytes())
        count += 1
if not count:
    raise SystemExit("No native parser licenses found; refusing to package")
print(f"Collected {count} third-party notices in {destination}")
